// Extract data from webhook
const items = $input.all();
const webhookData = items[0].json;

// Extract all form data from the webhook body
const cvContent = webhookData.cvContent || $input.first().json.body.cvContent;
const jobDescription = webhookData.jobDescription || $input.first().json.body.jobDescription;
const hiringManagerName = webhookData.hiringManagerName || $input.first().json.body.hiringManagerName;
const userPreferences = webhookData.userPreferences || $input.first().json.body.userPreferences;

// Fix boolean conversion for needsCoverLetter
let needsCoverLetter = false;
const coverLetterValue = webhookData.needsCoverLetter || $input.first().json.body.needsCoverLetter;

if (coverLetterValue === true || coverLetterValue === 'true' || coverLetterValue === '1' || coverLetterValue === 1) {
  needsCoverLetter = true;
}

return [{
  json: {
    cvContent: cvContent,
    jobDescription: jobDescription,
    hiringManagerName: hiringManagerName,
    needsCoverLetter: needsCoverLetter, // Now guaranteed to be true or false
    userPreferences: userPreferences,
    timestamp: new Date().toISOString()
  }
}];

