const atsData = $('ATS Scoring Expert').first().json.output;
const optimizedCV = $('CV Optimizer').first().json.output;
const needsCoverLetter = $('Code').first().json.needsCoverLetter;

let coverLetterContent = null;
if (needsCoverLetter) {
  coverLetterContent = $('Cover Letter Expert').first().json.output;
}

// 🎯 Only send what frontend needs
return {
  optimizedCv: optimizedCV,   // 👈 renamed here for frontend consistency
  atsScore: atsData.atsScore,
  recommendations:  atsData.recommendations || $('ATS Scoring Expert').first().json.output.recommendations,
  coverLetter: coverLetterContent
};

